CREATE OR REPLACE FUNCTION public.list_anonymous_bell_board(_section text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _section IN ('goods','returns','cars') THEN RETURN QUERY SELECT d.id,'vehicle'::text,d.from_place||' → '||d.to_place,d.vehicle_type FROM public.vehicle_bell_demands d WHERE d.category=_section AND public.account_allowed(d.user_id) AND (d.post_id IS NULL OR EXISTS(SELECT 1 FROM public.posts p WHERE p.id=d.post_id AND public.post_listing_visible(p))) AND (_section<>'goods' OR d.rang_at+interval '1 day'>now()) ORDER BY d.rang_at DESC; ELSE RETURN QUERY SELECT i.id,'post'::text,i.area,i.need FROM public.post_bell_interests i WHERE i.section=_section AND public.account_allowed(i.user_id) AND i.created_at+interval '30 days'>now() AND (NOT EXISTS(SELECT 1 FROM public.posts p WHERE p.id=i.post_id) OR EXISTS(SELECT 1 FROM public.posts p WHERE p.id=i.post_id AND public.post_listing_visible(p))) ORDER BY i.created_at DESC; IF _section='service-providers' THEN RETURN QUERY SELECT r.id,'service'::text,r.area,r.service FROM public.service_requests r WHERE public.account_allowed(r.user_id) AND r.created_at+interval '30 days'>now() ORDER BY r.created_at DESC; END IF; END IF; END $$;
CREATE OR REPLACE FUNCTION public.list_area_bell_board(_section text,_area text) RETURNS TABLE(id uuid,source text,area text,need text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT b.id,b.source,b.area,b.need FROM public.list_anonymous_bell_board(_section) b WHERE trim(coalesce(_area,''))='' OR (b.source<>'vehicle' AND lower(trim(b.area))=lower(trim(_area))) OR (b.source='vehicle' AND EXISTS(SELECT 1 FROM public.vehicle_bell_demands d WHERE d.id=b.id AND lower(trim(d.from_place))=lower(trim(_area)))); $$;
GRANT EXECUTE ON FUNCTION public.list_anonymous_bell_board(text),public.list_area_bell_board(text,text),public.list_free_work(text,text,text),public.list_free_work_interests(text,text,text),public.list_service_priority(text,text) TO anon,authenticated;
CREATE FUNCTION public.bell_pair_chat_signal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE caller uuid:=auth.uid(); body_text text:='గంట ద్వారా సంభాషణ ప్రారంభమైంది.'; post uuid; prior_claims text:=current_setting('request.jwt.claims',true); prior_sub text:=current_setting('request.jwt.claim.sub',true); reverse_claims jsonb; BEGIN IF caller IS NULL OR caller<>NEW.member_id OR caller=NEW.owner_id OR NOT public.account_allowed(caller) OR NOT public.account_allowed(NEW.owner_id) THEN RETURN NEW; END IF;
IF TG_TABLE_NAME='vehicle_demand_chat_pairs' AND (NEW.board_rang_at IS NULL OR (TG_OP='UPDATE' AND OLD.board_rang_at IS NOT NULL)) THEN RETURN NEW; END IF;
IF TG_TABLE_NAME='post_chat_pairs' THEN post:=NEW.post_id; SELECT CASE WHEN p.module='vehicle' THEN public.vehicle_bell_route(p.from_place,p.to_place) ELSE 'గంట ద్వారా సంభాషణ ప్రారంభమైంది.' END INTO body_text FROM public.posts p WHERE p.id=post; END IF;
IF TG_TABLE_NAME='vehicle_demand_chat_pairs' THEN SELECT public.vehicle_bell_route(d.from_place,d.to_place) INTO body_text FROM public.vehicle_bell_demands d WHERE d.id=NEW.demand_id; END IF;
body_text:=coalesce(body_text,'గంట ద్వారా సంభాషణ ప్రారంభమైంది.');
IF EXISTS(SELECT 1 FROM public.messages m WHERE m.sender_id=caller AND m.receiver_id=NEW.owner_id AND m.post_id IS NOT DISTINCT FROM post AND m.is_auto AND m.body=body_text) THEN RETURN NEW; END IF;
INSERT INTO public.messages(sender_id,receiver_id,post_id,body,is_auto) VALUES(caller,NEW.owner_id,post,body_text,true);
reverse_claims:=coalesce(nullif(prior_claims,'')::jsonb,'{}'::jsonb)||jsonb_build_object('sub',NEW.owner_id::text);
PERFORM set_config('request.jwt.claims',reverse_claims::text,true); PERFORM set_config('request.jwt.claim.sub',NEW.owner_id::text,true);
INSERT INTO public.messages(sender_id,receiver_id,post_id,body,is_auto) VALUES(NEW.owner_id,caller,post,body_text,true);
PERFORM set_config('request.jwt.claims',coalesce(prior_claims,''),true); PERFORM set_config('request.jwt.claim.sub',coalesce(prior_sub,''),true); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.bell_pair_chat_signal() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER bell_pair_chat_signal AFTER INSERT ON public.free_work_pairs FOR EACH ROW EXECUTE FUNCTION public.bell_pair_chat_signal();
CREATE TRIGGER bell_pair_chat_signal AFTER INSERT ON public.post_chat_pairs FOR EACH ROW EXECUTE FUNCTION public.bell_pair_chat_signal();
CREATE TRIGGER bell_pair_chat_signal AFTER UPDATE OF board_rang_at ON public.vehicle_demand_chat_pairs FOR EACH ROW EXECUTE FUNCTION public.bell_pair_chat_signal();